outputs.with:
**Finding (Correctness — Blocking):** Two defects on this line: `Array.prototype.sort` mutates `rows` in place, breaking callers that reuse the original array, and the comparator `a.time > b.time ? 1 : -1` returns `-1` instead of `0` when `a.time === b.time`, violating comparator transitivity and stability.

**Scope & Checks:** Static inspection of the provided line only; no project tests or typechecker ran.

**Correction:**
```ts
const sortedRows = [...rows].sort((a, b) => (a.time < b.time ? -1 : a.time > b.time ? 1 : 0));
```

**Regression Test:**
```ts
import { describe, expect, it } from "vitest";

interface Row {
  id: string;
  time: number;
}

const sortByTime = (rows: readonly Row[]): Row[] =>
  [...rows].sort((a, b) => (a.time < b.time ? -1 : a.time > b.time ? 1 : 0));

describe("sortByTime", () => {
  it("returns a sorted copy without mutating the caller's array or reordering ties", () => {
    const original: Row[] = [
      { id: "late", time: 30 },
      { id: "tie-1", time: 10 },
      { id: "tie-2", time: 10 },
    ];
    const sorted = sortByTime(original);

    expect(sorted.map((r) => r.id)).toEqual(["tie-1", "tie-2", "late"]);
    expect(original.map((r) => r.id)).toEqual(["late", "tie-1", "tie-2"]);
  });
});
```
